// Initialize onboarding workflow for new customer
const customer = $input.first().json;

const onboarding = {
  customerId: customer.id || customer.leadId,
  email: customer.email,
  name: `${customer.firstName || ''} ${customer.lastName || ''}`.trim(),
  company: customer.company,
  plan: customer.plan || 'standard',

  // Onboarding phases
  phases: [
    {
      name: 'welcome',
      status: 'pending',
      tasks: [
        { id: 'welcome_email', name: 'Send Welcome Email', status: 'pending' },
        { id: 'account_setup', name: 'Create Account', status: 'pending' },
        { id: 'assign_csm', name: 'Assign Success Manager', status: 'pending' }
      ]
    },
    {
      name: 'setup',
      status: 'pending',
      tasks: [
        { id: 'kickoff_call', name: 'Schedule Kickoff Call', status: 'pending' },
        { id: 'integration_guide', name: 'Send Integration Guide', status: 'pending' },
        { id: 'api_credentials', name: 'Generate API Credentials', status: 'pending' }
      ]
    },
    {
      name: 'activation',
      status: 'pending',
      tasks: [
        { id: 'first_integration', name: 'Complete First Integration', status: 'pending' },
        { id: 'training_session', name: 'Conduct Training', status: 'pending' },
        { id: 'success_check', name: '30-Day Success Check', status: 'pending' }
      ]
    }
  ],

  // Onboarding metadata
  createdAt: new Date().toISOString(),
  targetCompletionDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
  status: 'initiated'
};

return onboarding;

// Generate welcome email content
const onboarding = $input.first().json;

const welcomeEmail = {
  to: onboarding.email,
  subject: `Welcome to AutoScale, ${onboarding.name || 'there'}! 🚀`,
  template: 'welcome_customer',
  variables: {
    customerName: onboarding.name || 'Valued Customer',
    company: onboarding.company,
    plan: onboarding.plan,
    csmName: 'Your Success Manager', // Would be assigned dynamically
    loginUrl: 'https://app.autoscale.io/login',
    onboardingGuideUrl: 'https://docs.autoscale.io/getting-started',
    supportEmail: 'support@autoscale.io'
  },
  tracking: {
    campaignId: `onboarding_${onboarding.customerId}`,
    phase: 'welcome'
  }
};

// Update task status
onboarding.phases[0].tasks[0].status = 'completed';
onboarding.phases[0].tasks[0].completedAt = new Date().toISOString();

return { email: welcomeEmail, onboarding };

// Create internal tasks for the team
const data = $input.first().json;
const onboarding = data.onboarding;

const internalTasks = [
  {
    type: 'task',
    title: `New Customer Onboarding: ${onboarding.company || onboarding.name}`,
    description: `Setup and onboard new ${onboarding.plan} customer`,
    assignTo: 'customer_success_team',
    priority: 'high',
    dueDate: new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString(), // 2 days
    subtasks: [
      `Assign dedicated CSM`,
      `Review customer profile and goals`,
      `Schedule kickoff call`,
      `Prepare custom onboarding plan`
    ],
    metadata: {
      customerId: onboarding.customerId,
      customerEmail: onboarding.email,
      plan: onboarding.plan
    }
  },
  {
    type: 'task',
    title: `Technical Setup: ${onboarding.company}`,
    description: `Provision technical resources for new customer`,
    assignTo: 'engineering_team',
    priority: 'medium',
    dueDate: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(), // 3 days
    subtasks: [
      `Create API credentials`,
      `Setup sandbox environment`,
      `Configure webhooks`
    ],
    metadata: {
      customerId: onboarding.customerId
    }
  }
];

return { tasks: internalTasks, onboarding };

// Schedule follow-up reminders
const data = $('Code - Create Internal Tasks').first().json;
const onboarding = data.onboarding;

const reminders = [
  {
    type: 'reminder',
    title: `Day 3 Check-in: ${onboarding.company}`,
    scheduledFor: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(),
    action: 'send_checkin_email',
    template: 'onboarding_day3'
  },
  {
    type: 'reminder',
    title: `Week 1 Review: ${onboarding.company}`,
    scheduledFor: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
    action: 'schedule_progress_call',
    template: 'onboarding_week1'
  },
  {
    type: 'reminder',
    title: `30-Day Success Check: ${onboarding.company}`,
    scheduledFor: onboarding.targetCompletionDate,
    action: 'success_review',
    template: 'onboarding_complete'
  }
];

return {
  reminders,
  onboarding: {
    ...onboarding,
    status: 'in_progress',
    phases: onboarding.phases.map((phase, i) => ({
      ...phase,
      status: i === 0 ? 'in_progress' : 'pending'
    }))
  }
};
